const resp = $input.item.json;
const ctx = $('⚙️ Analisar Campanhas').item.json;

const text = (resp.content||[]).map(b=>b.type==='text'?b.text:'').join('');
let estrategia;
try {
  const clean = text.replace(/```json|```/g,'').trim();
  const match = clean.match(/\{[\s\S]*\}/);
  estrategia = match ? JSON.parse(match[0]) : { acao: 'manter', justificativa: 'Erro ao parsear' };
} catch(e) {
  estrategia = { acao: 'manter', justificativa: 'Erro: '+e.message };
}

const crypto = require('crypto');
const pid=ctx.pid, pk=ctx.pk, sid=ctx.sid, at=ctx.at;

let path, body_data;
const ts = Math.floor(Date.now()/1000);

if (estrategia.acao === 'criar') {
  path = '/api/v2/ads/create_campaign';
  body_data = {
    campaign_name: `[AUTO] ${ctx.produto.nome_produto} - ${new Date().toISOString().split('T')[0]}`,
    campaign_type: estrategia.tipo_campanha === 'search_ads' ? 1 : 2,
    daily_budget: Math.round(estrategia.orcamento_diario_brl * 100000),
    start_time: ts,
    end_time: ts + (30 * 24 * 3600),
    item_id: parseInt(ctx.produto.item_id_shopee || 0),
    keywords: (estrategia.palavras_chave||[]).map(kw=>({ keyword: kw, bid_price: Math.round(estrategia.bid_por_clique_brl * 100000), match_type: 1 }))
  };
} else if (estrategia.acao === 'otimizar') {
  path = '/api/v2/ads/update_campaign';
  body_data = {
    campaign_id: ctx.campanha_existente?.campaign_id,
    daily_budget: Math.round(estrategia.orcamento_diario_brl * 100000)
  };
} else if (estrategia.acao === 'pausar') {
  path = '/api/v2/ads/end_campaign';
  body_data = { campaign_id: ctx.campanha_existente?.campaign_id };
} else {
  // manter - não faz nada
  return [{ json: { acao: 'manter', produto: ctx.produto.nome_produto, justificativa: estrategia.justificativa, skip: true } }];
}

const sign = crypto.createHmac('sha256',pk).update(`${pid}${path}${ts}${at}${sid}`).digest('hex');

return [{
  json: {
    acao: estrategia.acao,
    produto: ctx.produto.nome_produto,
    justificativa: estrategia.justificativa,
    meta_roas: estrategia.meta_roas,
    skip: false,
    shopee_ads_url: `https://api.shopee.io${path}?partner_id=${pid}&timestamp=${ts}&access_token=${at}&shop_id=${sid}&sign=${sign}`,
    shopee_ads_body: body_data
  }
}];

const categorias = [
  'eletrônicos gadgets', 'acessórios celular smartphone',
  'beleza cosméticos maquiagem', 'fitness academia suplementos',
  'decoração casa utilidades', 'moda feminina tendência',
  'pet acessórios animais', 'bebê maternidade',
  'ferramentas casa jardim', 'papelaria artigos escritório'
];

const fontesBR = [
  'Dropi Brasil catálogo fornecedores dropshipping',
  'Bling ERP produtos mais vendidos dropshipping Brasil',
  'Wholesale Brazil fornecedores atacado',
  'Brás Online produtos moda atacado São Paulo',
  'Shopee Brasil mais vendidos trending',
  'Mercado Livre Brasil mais vendidos categoria'
];

return categorias.map(cat => ({
  json: { categoria: cat, fontes_br: fontesBR, timestamp: new Date().toISOString() }
}));

const resp = $input.item.json;
const categoria = $('📋 Definir Categorias BR').item.json.categoria;

const allText = (resp.content || []).map(b => b.type === 'text' ? b.text : '').join('\n');

let parsed;
try {
  const clean = allText.replace(/```json|```/g, '').trim();
  const match = clean.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { categoria, produtos: [] };
} catch(e) {
  parsed = { categoria, produtos: [] };
}

const top = (parsed.produtos || [])
  .sort((a, b) => (b.score_oportunidade || 0) - (a.score_oportunidade || 0))
  .slice(0, 5);

return top.map(p => ({
  json: {
    categoria: parsed.categoria || categoria,
    nome_produto: p.nome,
    preco_custo: p.preco_custo_br,
    preco_venda: p.preco_venda_shopee,
    margem: p.margem_liquida_percentual,
    prazo_entrega_dias: p.prazo_entrega_dias,
    disponivel_dropi: p.disponivel_dropi,
    fornecedor_nome: p.fornecedor_nome,
    plataforma_fornecedor: p.fornecedor_plataforma,
    fornecedor_url: p.fornecedor_url,
    volume_vendas: p.volume_vendas_estimado,
    tendencia: p.tendencia,
    concorrencia: p.concorrencia_shopee,
    score: p.score_oportunidade,
    justificativa: p.vantagem_competitiva,
    origem: 'fornecedor_br',
    data_pesquisa: new Date().toISOString().split('T')[0],
    status_validacao: p.score_oportunidade >= 7 ? 'validado' : 'monitorar'
  }
}));

const body = $input.item.json.body || $input.item.json;
const data = body.data || {};
const items = data.item_list || [];

return [{
  json: {
    shop_id: String(body.shop_id || ''),
    order_sn: data.ordersn || data.order_sn || '',
    buyer_username: data.buyer_username || '',
    buyer_phone: data.recipient_address?.phone || '',
    endereco: {
      nome: data.recipient_address?.name || '',
      telefone: data.recipient_address?.phone || '',
      logradouro: data.recipient_address?.full_address || '',
      cidade: data.recipient_address?.city || '',
      estado: data.recipient_address?.state || '',
      cep: data.recipient_address?.zipcode || ''
    },
    produtos: items.map(i => ({
      item_id: i.item_id,
      nome: i.item_name,
      sku: i.model_sku || i.item_sku,
      quantidade: i.model_quantity_purchased || 1,
      preco_unitario: (i.model_discounted_price || 0) / 100000
    })),
    valor_total: (data.total_amount || 0) / 100000
  }
}];

const pedido = $('⚙️ Extrair Pedido Completo').item.json;
const fornecedor = $input.item.json;

return [{
  json: {
    ...pedido,
    fornecedor_sku: fornecedor.sku_fornecedor || pedido.produtos[0].sku,
    fornecedor_id: fornecedor.fornecedor_id || '',
    plataforma_fornecedor: fornecedor.plataforma || 'dropi'
  }
}];

