const dados = $('⚙️ Parse Resposta Dropi').item.json;
const crypto = require('crypto');
const pid = 'SEU_PARTNER_ID_AQUI', pk = 'SUA_PARTNER_KEY_AQUI';
const sid = dados.shop_id, at = 'SEU_ACCESS_TOKEN_AQUI';
const path = '/api/v2/sellerchat/send_message';
const ts = Math.floor(Date.now() / 1000);
const sign = crypto.createHmac('sha256', pk).update(`${pid}${path}${ts}${at}${sid}`).digest('hex');

const rastreio = dados.rastreio;
const msg = rastreio
  ? `Olá ${dados.buyer_username}! 🎉 Seu pedido #${dados.order_sn} foi confirmado e já está sendo preparado pelo fornecedor!\n\n📦 Código de rastreio: ${rastreio}\n\nAcompanhe sua entrega pelo site dos Correios ou na aba "Meus Pedidos" da Shopee. Qualquer dúvida é só chamar! 😊`
  : `Olá ${dados.buyer_username}! ✅ Seu pedido #${dados.order_sn} foi confirmado e já está em processamento. Em breve você receberá o código de rastreio. 📦`;

return [{
  json: {
    ...dados,
    chat_url: `https://api.shopee.io/api/v2/sellerchat/send_message?partner_id=${pid}&timestamp=${ts}&access_token=${at}&shop_id=${sid}&sign=${sign}`,
    chat_body: {
      toId: 0,
      messageType: 'text',
      content: { text: msg },
      conversationId: dados.order_sn
    }
  }
}];
